use diesel::connection::SimpleConnection;
use diesel::prelude::*;
use embedag_diesel::cte::{CteHierarchyBuilder, HierarchicalNode, HierarchyItem};
use embedag_example_receipts::{
    categorize_ticket_invoice, run_receipt_categories_sqlite_migration, InvoiceItem, InvoiceTicket,
    ReceiptCategoryRecord,
};

#[test]
fn test_macro_generated_table_config_and_context_for_llm() {
    // Verify that the table configuration is fully generated by the macro
    let config = ReceiptCategoryRecord::table_config();
    assert_eq!(config.table_name, "receipt_categories");
    assert_eq!(config.id_column, "category_id");
    assert_eq!(config.parent_column, "parent_category_id");
    assert_eq!(config.name_column, "category_name");
    assert!(config.description.is_some());

    // Verify that table context is formatted for feeding the LLM
    let context = ReceiptCategoryRecord::table_context();
    assert!(context.contains("Table: receipt_categories"));
    assert!(context.contains("- Key Column: category_id"));
    assert!(context.contains("- Parent Column: parent_category_id"));
    assert!(context.contains("- Label Column: category_name"));
    assert!(context.contains("Retail purchase ticket receipt categories hierarchy"));
}

#[test]
fn test_developer_custom_migration_and_invoice_categorization_cte_sqlite() {
    let mut conn = diesel::SqliteConnection::establish(":memory:").expect("in-memory sqlite");

    // 1. Run developer's custom migration (does NOT use hardcoded semantic_nodes/edges)
    run_receipt_categories_sqlite_migration(&mut conn).expect("custom receipt migration");

    // 2. Input purchase ticket invoice
    let ticket = InvoiceTicket {
        store: "FreshMarket".into(),
        date: "2026-10-12".into(),
        card: "**** 8899".into(),
        items: vec![
            InvoiceItem {
                item_name: "Organic Oat Milk".into(),
                price: 3.99,
                quantity: 2,
            },
            InvoiceItem {
                item_name: "Artisan Sourdough Loaf".into(),
                price: 4.50,
                quantity: 1,
            },
            InvoiceItem {
                item_name: "Paper Towels".into(),
                price: 2.25,
                quantity: 2,
            },
        ],
        total: 16.98,
    };

    // 3. Derive hierarchical categories from invoice items
    let categories: Vec<ReceiptCategoryRecord> = categorize_ticket_invoice(&ticket);
    assert!(
        !categories.is_empty(),
        "Must generate category hierarchy from ticket"
    );

    // Verify trait implementation
    for cat in &categories {
        assert_eq!(cat.node_id(), cat.category_id);
        assert_eq!(cat.node_name(), &cat.category_name);
    }

    // 4. Fill developer's custom table with generated categories
    for cat in &categories {
        let parent_val = match &cat.parent_category_id {
            Some(p) => format!("'{}'", p),
            None => "NULL".to_string(),
        };
        let sql = format!(
            "INSERT INTO receipt_categories (category_id, parent_category_id, category_name, entity_level) \
             VALUES ('{}', {}, '{}', '{}');",
            cat.category_id, parent_val, cat.category_name, cat.entity_level
        );
        conn.batch_execute(&sql).expect("insert category row");
    }

    // 5. Query hierarchical lineage using macro-generated table_config and CteHierarchyBuilder
    let config = ReceiptCategoryRecord::table_config();

    let oat_milk_item = categories
        .iter()
        .find(|c| c.category_name == "Organic Oat Milk")
        .expect("oat milk item exists");

    let ancestors: Vec<HierarchyItem> = CteHierarchyBuilder::fetch_ancestors_sqlite(
        &mut conn,
        &config,
        &oat_milk_item.category_id,
        10,
    )
    .expect("ancestors recursive CTE query");

    // Ancestor lineage must be: Milk & Dairy (depth 1) -> Dairy & Plant Alternatives (depth 2) -> FreshMarket (depth 3)
    assert_eq!(
        ancestors.len(),
        3,
        "Must retrieve 3 levels of ancestor categories"
    );
    assert_eq!(ancestors[0].depth, 1);
    assert_eq!(ancestors[0].name, "Milk & Dairy");
    assert_eq!(ancestors[1].depth, 2);
    assert_eq!(ancestors[1].name, "Dairy & Plant Alternatives");
    assert_eq!(ancestors[2].depth, 3);
    assert_eq!(ancestors[2].name, "FreshMarket");

    // 6. Query all descendant subcategories from the store root node using macro-generated table_config
    let store_root = categories
        .iter()
        .find(|c| c.entity_level == "store_root")
        .expect("store root exists");

    let descendants: Vec<HierarchyItem> = CteHierarchyBuilder::fetch_descendants_sqlite(
        &mut conn,
        &config,
        &store_root.category_id,
        10,
    )
    .expect("descendants recursive CTE query");

    // Total descendants must include 3 departments, 3 subcategories, and 3 items = 9 nodes
    assert_eq!(
        descendants.len(),
        9,
        "Must traverse all 9 downstream descendant category nodes"
    );

    // Verify depth ordering
    let depths: Vec<i32> = descendants.iter().map(|d| d.depth).collect();
    assert!(
        depths.windows(2).all(|w| w[0] <= w[1]),
        "Descendants must be returned ordered by depth"
    );
}

#[test]
fn test_diamond_dag_deduplication_with_recursive_not_all() {
    let mut conn = diesel::SqliteConnection::establish(":memory:").expect("in-memory sqlite");
    run_receipt_categories_sqlite_migration(&mut conn).expect("custom receipt migration");

    conn.batch_execute(
        "INSERT INTO receipt_categories (category_id, parent_category_id, category_name, entity_level) VALUES
         ('root', NULL, 'General Retail', 'root'),
         ('cat_a', 'root', 'Specialty Food', 'dept'),
         ('cat_b', 'root', 'Organic Pantry', 'dept'),
         ('leaf', 'cat_a', 'Artisan Honey', 'item');
         INSERT INTO receipt_categories (category_id, parent_category_id, category_name, entity_level) VALUES
         ('leaf_alt', 'cat_b', 'Artisan Honey', 'item');",
    )
    .expect("insert diamond rows");

    // Traversal using macro-generated table_config directly from model
    let config = ReceiptCategoryRecord::table_config();
    let ancestors = CteHierarchyBuilder::fetch_ancestors_dedup_sqlite(&mut conn, &config, "leaf", 5)
        .expect("ancestors dedup");

    assert!(!ancestors.is_empty());
    assert_eq!(ancestors[0].name, "Specialty Food");
    assert_eq!(ancestors[1].name, "General Retail");
}

#[tokio::test]
async fn test_developer_custom_migration_and_invoice_categorization_cte_postgres() {
    use diesel_async::{AsyncConnection, AsyncPgConnection};
    use embedag_diesel::harness::PostgresHarness;
    use embedag_example_receipts::run_receipt_categories_postgres_migration;

    let harness = PostgresHarness::start().await.expect("start postgres harness");
    let client = harness.connect().await.expect("connect client");

    // 1. Run developer's custom PostgreSQL migration
    run_receipt_categories_postgres_migration(&client)
        .await
        .expect("run pg custom receipt migration");

    // 2. Establish diesel-async AsyncPgConnection
    let db_url = format!(
        "postgres://postgres:postgres@{}:{}/postgres",
        harness.host, harness.port
    );
    let mut async_conn = AsyncPgConnection::establish(&db_url)
        .await
        .expect("connect async pg connection");

    // 3. Prepare ticket and generate categories
    let ticket = InvoiceTicket {
        store: "WholeOrganics".into(),
        date: "2026-10-12".into(),
        card: "**** 1122".into(),
        items: vec![
            InvoiceItem {
                item_name: "Fresh Whole Milk".into(),
                price: 4.99,
                quantity: 1,
            },
            InvoiceItem {
                item_name: "French Baguette Bread".into(),
                price: 3.50,
                quantity: 2,
            },
        ],
        total: 11.99,
    };

    let categories = categorize_ticket_invoice(&ticket);

    // 4. Fill custom table
    for cat in &categories {
        let parent_val = match &cat.parent_category_id {
            Some(p) => format!("'{}'", p),
            None => "NULL".to_string(),
        };
        let sql = format!(
            "INSERT INTO receipt_categories (category_id, parent_category_id, category_name, entity_level) \
             VALUES ('{}', {}, '{}', '{}');",
            cat.category_id, parent_val, cat.category_name, cat.entity_level
        );
        client.batch_execute(&sql).await.expect("insert category row");
    }

    let config = ReceiptCategoryRecord::table_config();

    let milk_item = categories
        .iter()
        .find(|c| c.category_name == "Fresh Whole Milk")
        .expect("milk item");

    // 5. Query ancestors via macro-generated config on PostgreSQL
    let ancestors = CteHierarchyBuilder::fetch_ancestors_pg_async(
        &mut async_conn,
        &config,
        &milk_item.category_id,
        10,
    )
    .await
    .expect("fetch ancestors pg async");

    assert_eq!(ancestors.len(), 3);
    assert_eq!(ancestors[0].depth, 1);
    assert_eq!(ancestors[0].name, "Milk & Dairy");
    assert_eq!(ancestors[1].depth, 2);
    assert_eq!(ancestors[1].name, "Dairy & Plant Alternatives");
    assert_eq!(ancestors[2].depth, 3);
    assert_eq!(ancestors[2].name, "WholeOrganics");

    // 6. Query descendants from root via macro-generated config on PostgreSQL
    let root = categories
        .iter()
        .find(|c| c.entity_level == "store_root")
        .expect("store root");

    let descendants = CteHierarchyBuilder::fetch_descendants_pg_async(
        &mut async_conn,
        &config,
        &root.category_id,
        10,
    )
    .await
    .expect("fetch descendants pg async");

    // 2 departments + 2 subcategories + 2 items = 6 descendants
    assert_eq!(descendants.len(), 6);
}
